// Filter out emails we've already ingested
const incoming = $input.all();
if (incoming.length === 0) return [{ json: { skipped: true, reason: 'no new emails', count: 0 } }];

return incoming.map(it => ({
  json: {
    gmailId: it.json.id,
    threadId: it.json.threadId,
    subject: (it.json.payload?.headers || []).find(h => h.name === 'Subject')?.value || '',
    from: (it.json.payload?.headers || []).find(h => h.name === 'From')?.value || '',
    receivedAt: new Date(parseInt(it.json.internalDate || '0')).toISOString(),
    snippet: it.json.snippet || '',
    body: it.json.payload?.parts ? extractBody(it.json.payload) : (it.json.payload?.body?.data ? Buffer.from(it.json.payload.body.data, 'base64').toString('utf8') : '')
  }
}));

function extractBody(payload) {
  if (payload.body?.data) {
    return Buffer.from(payload.body.data, 'base64').toString('utf8');
  }
  for (const part of (payload.parts || [])) {
    if (part.mimeType === 'text/plain' && part.body?.data) {
      return Buffer.from(part.body.data, 'base64').toString('utf8');
    }
    if (part.parts) {
      const nested = extractBody(part);
      if (nested) return nested;
    }
  }
  return '';
}

const items = $input.all();
const normalized = $('Normalize Gmail Messages').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const existing = items[i].json;
  const isNew = Array.isArray(existing) && existing.length === 0;
  if (isNew && normalized[i]) {
    out.push({ json: normalized[i].json });
  }
}
return out.length > 0 ? out : [{ json: { skipped: true, reason: 'all already ingested' } }];

