// Haiku returns JSON array. Each email can produce N query rows.
const items = $input.all();
const sources = $('Filter New Only').all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const haiku = items[i].json;
  const src = sources[i]?.json || {};
  if (!src.gmailId) continue;

  let queries = [];
  try {
    const text = haiku.content?.[0]?.text || '';
    // Strip any markdown code fences if Haiku used them despite instructions
    const cleaned = text.replace(/^```json\s*|\s*```$/g, '').trim();
    queries = JSON.parse(cleaned);
    if (!Array.isArray(queries)) queries = [];
  } catch (e) {
    console.log('parse err on gmail', src.gmailId, ':', e.message);
    queries = [];
  }

  for (const q of queries) {
    out.push({ json: {
      gmail_message_id: src.gmailId + '::' + (q.query_text || '').slice(0,64),
      received_at: src.receivedAt,
      subject: src.subject || null,
      source: 'haro',
      journalist_name: q.journalist_name || null,
      outlet: q.outlet || null,
      category: q.category || null,
      query_text: (q.query_text || '').slice(0, 4000),
      deadline: q.deadline || null,
      requirements: q.requirements || null,
      email_to_pitch: q.email_to_pitch || null,
      status: 'new'
    } });
  }
}

return out.length > 0 ? out : [{ json: { skipped: true, reason: 'no queries extracted' } }];

